{
  "speakers": [
    {
      "speaker_id": "sp4",
      "overview": "sp4 作为执行董事，介绍了公司基本情况（娱乐健身比赛餐饮一体的篮球主题公司）、上半年运营情况、团队管理、市场分析、销售推广和风险评估，提出需开发健康餐、与NBA合作、引入筋膜枪等项目，并建议下半年重点发展篮球周边服务和健康相关业务。"
    },
    {
      "speaker_id": "sp7",
      "overview": "sp7 作为研发部，提出在浴室引入药浴、牛奶浴等体验项目，计划与国外合作引入筋膜枪用于篮球后肌肉放松，建议开发乒乓球项目、与李宁等品牌合作，以及开发健康餐和能量饮料，同时强调需评估项目风险。"
    },
    {
      "speaker_id": "sp1",
      "overview": "sp1 作为董事长，主持会议总结各部门上月工作，强调公司需维持篮球主业并开拓其他市场以避免亏损，建议加强管理、关注健康相关业务，以及在疫情后逐步恢复运营，同时要求各部门确保下半年业务稳定。"
    },
    {
      "speaker_id": "sp3",
      "overview": "sp3 作为市场营销，指出公司目前亏损，需通过开发乒乓球等其他市场弥补亏损，提出与冷饮公司合作、赠送乒乓球拍等策略，以及在疫情下保持运营的方案。"
    },
    {
      "speaker_id": "sp6",
      "overview": "sp6 作为风险评估，分析篮球市场受疫情影响较小，建议通过直播篮球赛、与专业乒乓球队合作、开设篮球课等方式促进业务，同时强调需谨慎评估新市场风险。"
    }
  ]
}
